    <title>工作流变量更新 · 折叠栏</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" />
    <style>
        /* ============================================================
                   1. 全局重置 & 主题变量 (无外部背景占位)
                   ============================================================ */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: transparent;
            min-height: auto;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            padding: 20px;
        }

        /* ---------- 亮色主题 — 羊皮卷色系 ---------- */
        :root {
            /* 卡片背景 */
            --bg-card: #f5e6c8;
            --bg-card-hover: #ebd6b0;
            --border-color: rgba(139, 115, 85, 0.25);
            --shadow-card: 0 12px 32px -8px rgba(90, 62, 43, 0.15), 0 4px 12px -4px rgba(90, 62, 43, 0.08);
            --shadow-card-hover: 0 20px 48px -12px rgba(90, 62, 43, 0.25), 0 8px 24px -6px rgba(90, 62, 43, 0.12);

            /* 头部 */
            --header-bg: rgba(245, 230, 200, 0.85);
            --header-border: rgba(139, 115, 85, 0.15);
            --header-text: #5a3e2b;
            --header-icon: #7a5a3a;

