            --toggle-bg: #d4b48c;
            --toggle-dot: #f5e6c8;
            --toggle-shadow: 0 2px 8px rgba(90, 62, 43, 0.15);

            /* 滚动条 */
            --scrollbar-track: rgba(90, 62, 43, 0.05);
            --scrollbar-thumb: rgba(139, 115, 85, 0.3);
        }

        /* ---------- 暗色主题 (保持不变) ---------- */
        [data-theme="dark"] {
            --bg-card: rgba(22, 28, 40, 0.85);
            --bg-card-hover: rgba(28, 36, 52, 0.95);
            --border-color: rgba(255, 255, 255, 0.06);
            --shadow-card: 0 12px 32px -8px rgba(0, 0, 0, 0.50), 0 4px 12px -4px rgba(0, 0, 0, 0.25);
            --shadow-card-hover: 0 20px 48px -12px rgba(0, 0, 0, 0.60), 0 8px 24px -6px rgba(0, 0, 0, 0.30);

            --header-bg: rgba(22, 28, 40, 0.80);
            --header-border: rgba(255, 255, 255, 0.05);
