            backdrop-filter: blur(12px) saturate(1.4);
            -webkit-backdrop-filter: blur(12px) saturate(1.4);
            border-bottom: 1px solid var(--header-border);
            cursor: pointer;
            user-select: none;
            transition: background 0.3s ease, border-color 0.3s ease;
            position: relative;
            z-index: 2;
