        .fold-header:hover {
            background: var(--bg-card-hover);
        }

        .fold-header-left {
            display: flex;
            align-items: center;
            gap: 10px;
            min-width: 0;
            flex: 1;
        }

        .fold-header-left .icon-wrap {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 18px;
            height: 18px;
            flex-shrink: 0;
            font-size: 11px;
            color: var(--header-icon);
            transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), color 0.3s ease;
        }

        .fold-header-left .icon-wrap .fa-chevron-right {
            transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .fold-card.open .fold-header-left .icon-wrap .fa-chevron-right {
            transform: rotate(90deg);
        }

        .fold-header-left .title {
            font-size: 12px;
            font-weight: 600;
            letter-spacing: 0.02em;
