        @keyframes pulse-dot {
            0%, 100% { opacity: 0.6; transform: scale(0.9); }
            50% { opacity: 1; transform: scale(1.2); }
        }

        .fold-header-right {
            display: flex;
            align-items: center;
            gap: 10px;
            flex-shrink: 0;
        }

        .fold-header-right .var-count {
            font-size: 10px;
            font-weight: 500;
            color: var(--header-icon);
            background: var(--toggle-bg);
            padding: 1px 8px;
            border-radius: 100px;
            letter-spacing: 0.01em;
            opacity: 0.7;
        }

        /* ============================================================
                   4. 主题切换按钮
                   ============================================================ */
        .theme-toggle {
            position: relative;
            width: 36px;
            height: 20px;
            border: none;
            border-radius: 100px;
            background: var(--toggle-bg);
            box-shadow: var(--toggle-shadow), inset 0 1px 2px rgba(0, 0, 0, 0.04);
            cursor: pointer;
            transition: background 0.35s ease, box-shadow 0.35s ease;
            flex-shrink: 0;
            outline: none;
            -webkit-tap-highlight-color: transparent;
        }

        .theme-toggle::after {
            content: '';
            position: absolute;
            top: 2px;
            left: 2px;
            width: 16px;
            height: 16px;
            border-radius: 50%;
            background: var(--toggle-dot);
            box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
            transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), background 0.35s ease;
        }

        [data-theme="dark"] .theme-toggle::after {
            transform: translateX(16px);
        }

        .theme-toggle .toggle-icons {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 4px;
            pointer-events: none;
            font-size: 9px;
        }

        .theme-toggle .toggle-icons .fa-sun { color: #fbbf24; text-shadow: 0 0 6px rgba(251, 191, 36, 0.30); }
        .theme-toggle .toggle-icons .fa-moon { color: #94a3b8; text-shadow: 0 0 6px rgba(148, 163, 184, 0.20); }
        [data-theme="dark"] .theme-toggle .toggle-icons .fa-sun { color: #fcd34d; }
        [data-theme="dark"] .theme-toggle .toggle-icons .fa-moon { color: #e2e8f0; }

        .theme-toggle:hover {
            box-shadow: var(--toggle-shadow), 0 0 0 3px var(--accent-glow);
        }
        .theme-toggle:active::after {
            transform: scale(0.85);
        }
        [data-theme="dark"] .theme-toggle:active::after {
            transform: translateX(16px) scale(0.85);
        }

        /* ============================================================
                   5. 内容区域
                   ============================================================ */
        .fold-content {
            max-height: 0;
            overflow: hidden;
            opacity: 0;
            background: var(--content-bg);
            backdrop-filter: blur(8px) saturate(1.2);
            -webkit-backdrop-filter: blur(8px) saturate(1.2);
            border-top: 1px solid transparent;
            transition: max-height 0.55s cubic-bezier(0.16, 1, 0.3, 1),
                        padding 0.4s ease,
                        opacity 0.35s ease,
                        border-color 0.4s ease;
        }

        .fold-card.open .fold-content {
            max-height: 600px;
            opacity: 1;
            padding: 18px 20px 20px 20px;
            border-top-color: var(--content-border);
        }

        .fold-content-inner {
            font-family: 'JetBrains Mono', 'Fira Code', 'SF Mono', 'Menlo', 'Monaco', 'Consolas', monospace;
            font-size: 13px;
            line-height: 1.8;
            color: var(--content-text);
            white-space: pre-wrap;
            word-break: break-word;
            tab-size: 2;
            max-height: 520px;
            overflow-y: auto;
            padding-right: 4px;
            /* 纯文本，无任何装饰 */
        }

        .fold-content-inner::-webkit-scrollbar {
            width: 4px;
        }
        .fold-content-inner::-webkit-scrollbar-track {
            background: var(--scrollbar-track);
            border-radius: 100px;
        }
        .fold-content-inner::-webkit-scrollbar-thumb {
            background: var(--scrollbar-thumb);
            border-radius: 100px;
            transition: background 0.3s ease;
        }
        .fold-content-inner::-webkit-scrollbar-thumb:hover {
            background: var(--accent-start);
        }

