                   7. 响应式
                   ============================================================ */
        @media (max-width: 500px) {
            .fold-header {
                height: 26px;
                min-height: 26px;
                padding: 0 10px 0 14px;
            }
            .fold-header-left .title { font-size: 10px; }
            .fold-header-left .icon-wrap { width: 14px; height: 14px; font-size: 9px; }
            .fold-header-right .var-count { font-size: 8px; padding: 0 6px; }
            .theme-toggle { width: 30px; height: 17px; }
            .theme-toggle::after { width: 13px; height: 13px; top: 2px; left: 2px; }
            [data-theme="dark"] .theme-toggle::after { transform: translateX(13px); }
            [data-theme="dark"] .theme-toggle:active::after { transform: translateX(13px) scale(0.85); }
