            .fold-content-inner { font-size: 11px; line-height: 1.7; }
            .fold-card.open .fold-content { padding: 12px 14px 14px 14px; max-height: 400px; }
            .fold-content-inner { max-height: 340px; }
            .fold-footer { font-size: 7px; padding: 0 14px 4px 14px; }
        }

        /* 入场动画 */
        .fold-wrapper {
            animation: fade-up 0.6s cubic-bezier(0.16, 1, 0.3, 1) both;
            animation-delay: 0.1s;
        }
        @keyframes fade-up {
            0% { opacity: 0; transform: translateY(12px) scale(0.98); }
            100% { opacity: 1; transform: translateY(0) scale(1); }
        }
    </style>
</head>
<body>

    <div class="fold-wrapper">
        <div class="fold-card" id="foldCard">

            <!-- ======== 极窄头部 ======== -->
            <div class="fold-header" id="foldHeader" role="button" tabindex="0" aria-expanded="false">
                <div class="fold-header-left">
                    <span class="icon-wrap">
                        <i class="fas fa-chevron-right"></i>
                    </span>
                    <span class="title">
                        <span class="accent">⟡</span> 工作流变量更新
                    </span>
                    <span class="status-dot"></span>
                </div>
                <div class="fold-header-right">
                    <span class="var-count">变量</span>
                    <button class="theme-toggle" id="themeToggle" aria-label="切换主题">
                        <span class="toggle-icons">
                            <i class="fas fa-sun"></i>
                            <i class="fas fa-moon"></i>
                        </span>
                    </button>
                </div>
            </div>

            <!-- ======== 内容区域 ======== -->
            <div class="fold-content">
                <div class="fold-content-inner" id="contentInner">$1</div>
            </div>

            <!-- ======== 底部微标 ======== -->
            <div class="fold-footer">
                <span><i class="fas fa-code"></i> 纯文本 · 变量快照</span>
                <span><i class="fas fa-circle" style="font-size:4px;"></i></span>
                <span id="timestampLabel"></span>
            </div>

        </div>
    </div>

    <script>
        // ================================================================
        //  仅保留折叠切换 & 主题切换功能，无任何数据注入
        // ================================================================
        let isOpen = false;
        let currentTheme = 'dark';

        const foldCard = document.getElementById('foldCard');
        const foldHeader = document.getElementById('foldHeader');
        const themeToggle = document.getElementById('themeToggle');
        const timestampLabel = document.getElementById('timestampLabel');

        // 折叠切换
        function toggleFold() {
            isOpen = !isOpen;
            foldCard.classList.toggle('open', isOpen);
            foldHeader.setAttribute('aria-expanded', isOpen);
        }

        foldHeader.addEventListener('click', function(e) {
            if (e.target.closest('.theme-toggle')) return;
            toggleFold();
        });

        foldHeader.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                toggleFold();
            }
        });

        // 主题切换
        function setTheme(theme) {
            currentTheme = theme;
            document.documentElement.setAttribute('data-theme', theme);
            try { localStorage.setItem('fold-theme', theme); } catch (_) {}
        }

        function toggleTheme() {
            const next = currentTheme === 'light' ? 'dark' : 'light';
            setTheme(next);
        }

        themeToggle.addEventListener('click', function(e) {
            e.stopPropagation();
            toggleTheme();
        });

        function loadThemePreference() {
            try {
                const stored = localStorage.getItem('fold-theme');
                if (stored === 'light' || stored === 'dark') {
                    setTheme(stored);
                    return;
                }
            } catch (_) {}
            if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
                setTheme('light');
            } else {
                setTheme('dark');
            }
        }

        // 底部时间戳
        function setTimestamp() {
            const now = new Date();
            const ts = now.toLocaleString('zh-CN', {
                hour12: false,
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit'
            });
            timestampLabel.textContent = `📋 ${ts}`;
        }

        // 初始化 (默认收起)
        loadThemePreference();
        setTimestamp();
        foldCard.classList.remove('open');
        foldHeader.setAttribute('aria-expanded', 'false');
        isOpen = false;

        // 系统主题监听
        if (window.matchMedia) {
            const media = window.matchMedia('(prefers-color-scheme: light)');
            media.addEventListener('change', function(e) {
                try {
                    if (!localStorage.getItem('fold-theme')) {
                        setTheme(e.matches ? 'light' : 'dark');
                    }
                } catch (_) {}
            });
        }
    </script>

</body>
</html>
